// SPDX-License-Identifier: MIT
pragma solidity 0.8.35;

import {IConetProofVerifier} from "../IConetProofVerifier.sol";

/// @title ExternalTreasuryMockVerifier
/// @notice Test-only verifier. A proof is accepted only if the test registered those exact bytes for that message kind.
contract ExternalTreasuryMockVerifier is IConetProofVerifier {
    error UnknownProof();

    mapping(bytes32 proofHash => bool) private _hasAllowlist;
    mapping(bytes32 proofHash => Allowlist) private _allowlist;
    mapping(bytes32 proofHash => bool) private _hasBurn;
    mapping(bytes32 proofHash => Burn) private _burn;
    mapping(bytes32 proofHash => bool) private _hasRefund;
    mapping(bytes32 proofHash => Refund) private _refund;

    function registerAllowlist(bytes calldata proof, Allowlist calldata m) external {
        bytes32 k = keccak256(proof);
        _hasAllowlist[k] = true;
        _allowlist[k] = m;
    }

    function registerBurn(bytes calldata proof, Burn calldata b) external {
        bytes32 k = keccak256(proof);
        _hasBurn[k] = true;
        _burn[k] = b;
    }

    function registerRefund(bytes calldata proof, Refund calldata r) external {
        bytes32 k = keccak256(proof);
        _hasRefund[k] = true;
        _refund[k] = r;
    }

    function verifyAllowlist(bytes calldata proof) external view returns (Allowlist memory) {
        bytes32 k = keccak256(proof);
        if (!_hasAllowlist[k]) revert UnknownProof();
        return _allowlist[k];
    }

    function verifyBurn(bytes calldata proof) external view returns (Burn memory) {
        bytes32 k = keccak256(proof);
        if (!_hasBurn[k]) revert UnknownProof();
        return _burn[k];
    }

    function verifyRefund(bytes calldata proof) external view returns (Refund memory) {
        bytes32 k = keccak256(proof);
        if (!_hasRefund[k]) revert UnknownProof();
        return _refund[k];
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.35;

/// @title IConetProofVerifier
/// @notice Checks CoNET-side messages against a finalized CoNET state. This verifier is the only trust root the
/// treasury relies on for whitelist changes, releases and refunds. The committee-signature path is not modelled here.
interface IConetProofVerifier {
    /// @notice A governance whitelist message. `chainId` and `treasury` bind it to one deployment.
    struct Allowlist {
        uint256 chainId;
        address treasury;
        address token;
        bool add;
        uint256 version;
        uint256 cap;
        bytes32 codeHash;
    }

    /// @notice A CoNET burn that releases `amount` of `token` to `recipient` on this chain.
    struct Burn {
        uint256 chainId;
        address treasury;
        address token;
        address recipient;
        uint256 amount;
        bytes32 burnId;
    }

    /// @notice One proof, at one finalized CoNET block, that the route is disabled and that `depositId` was never minted.
    struct Refund {
        uint256 chainId;
        address treasury;
        bytes32 depositId;
        address token;
        address depositor;
        uint256 amount;
    }

    function verifyAllowlist(bytes calldata proof) external view returns (Allowlist memory);

    function verifyBurn(bytes calldata proof) external view returns (Burn memory);

    function verifyRefund(bytes calldata proof) external view returns (Refund memory);
}
